import assert from 'node:assert/strict';
import { createServer } from 'node:http';
import { mkdtemp, mkdir, writeFile, readFile, symlink } from 'node:fs/promises';
import { join } from 'node:path';
import { createHash } from 'node:crypto';
import { McpClient, parseFooter, type Footer } from '/home/genie/orca/workspaces/genie/mikro-engine-split/scripts/mikro/call.ts';
import { z } from '/home/genie/orca/workspaces/genie/mikro-engine-split/node_modules/zod/index.js';
const toolResultSchema = z.object({
  isError: z.boolean().optional(),
  content: z.array(z.object({ type: z.literal('text'), text: z.string() })).nonempty(),
  structuredContent: z.object({ answer: z.string(), session_id: z.string() }),
}).passthrough();
type ToolResult = z.infer<typeof toolResultSchema>;
const toolListSchema = z.object({ tools: z.array(z.object({ name: z.string() })) });
const terminalProofSchema = z.object({
  cases: z.array(z.object({
    name: z.string(),
    outcome: z.object({ text: z.string() }),
    partialObservation: z.object({
      coverage: z.literal('partial'), iterations: z.number(),
      subtotal: z.object({ inputTokens: z.number(), outputTokens: z.number(), totalCost: z.number() }),
      totals: z.null(),
    }).nullable(),
  })),
});
const integration = '/home/genie/orca/workspaces/genie/mikro-engine-split';
const proofRoot = await mkdtemp('/home/genie/.local/share/mikro-engine-split/experiments-g8/repair4-stdio-proof-');
const packets: Array<{ index: number; request: unknown; usage: unknown; answer: string }> = [];
let mode = 'invalid';
const server = createServer(async (request, response) => {
  let body = '';
  for await (const chunk of request) body += chunk;
  const answer = mode === 'valid' ? 'FINAL({"wanted":true})' : 'FINAL({"wrong":true})';
  const usage = { prompt_tokens: 11, completion_tokens: 7, total_tokens: 18 };
  packets.push({ index: packets.length + 1, request: JSON.parse(body), usage, answer });
  response.writeHead(200, { 'Content-Type': 'text/event-stream' });
  response.end(`data: ${JSON.stringify({ id: 'local-stdio-repair4', object: 'chat.completion.chunk', model: 'control', choices: [{ index: 0, delta: { role: 'assistant', content: answer }, finish_reason: 'stop' }], usage })}\n\ndata: [DONE]\n\n`);
});
await new Promise<void>(resolve => server.listen(0, '127.0.0.1', resolve));
const address = server.address();
assert(address && typeof address !== 'string');
const home = join(proofRoot, 'home');
const bin = join(proofRoot, 'bin');
const project = join(proofRoot, 'project');
const agentDir = join(project, '.mikro', 'agents', 'receipt-proof');
await Promise.all([mkdir(home, { recursive: true }), mkdir(bin), mkdir(agentDir, { recursive: true })]);
await symlink(join(integration, 'mikro/dist/src/cli.js'), join(bin, 'mikro'));
const schema = { type: 'object', required: ['wanted'], properties: { wanted: { type: 'boolean' } }, additionalProperties: false };
const keyFile = join(proofRoot, 'fixture-api-key');
await writeFile(keyFile, 'fixture-only-not-a-credential', { mode: 0o600, flag: 'wx' });
const output: { schema: Record<string, unknown> | null } = { schema };
const config = { model: { provider: 'receipt-fixture', model: 'control' }, providers: { 'receipt-fixture': { 'base-url': `http://127.0.0.1:${address.port}/v1`, 'api-key-file': keyFile, models: { control: { cost: { input: 1, output: 2 } } } } }, output, budget: { maxDepth: 0 }, storage: { enabled: 'never' }, cache: { enabled: false } };
const configPath = join(project, '.mikro', 'mikro.yaml');
await writeFile(configPath, JSON.stringify(config), { mode: 0o600 });
await writeFile(join(agentDir, 'agent.yaml'), 'schema_version: 1\nshape: single-step\nengine: rlm\nmodel: receipt-fixture/control\nbudget:\n  max_iterations: 1\n', { mode: 0o600 });
const client = new McpClient(project, { PATH: `${bin}:/home/genie/.hermes/node/bin:/usr/local/bin:/usr/bin:/bin`, HOME: home, TMPDIR: proofRoot, GENIE_HOME: join(home, '.genie'), MIKRO_AGENTS_DIR: join(project, '.mikro', 'agents') });
const outcomes: Array<{ name: string; result: ToolResult; completeFooter: Footer; packets: number }> = [];
try {
  await client.request('initialize', { protocolVersion: '2024-11-05', capabilities: {}, clientInfo: { name: 'genie-real-client-repair4-smoke', version: 'local' } }, 30000);
  client.notify('notifications/initialized');
  const listed = toolListSchema.parse(await client.request('tools/list', {}, 30000));
  assert(listed.tools.some(tool => tool.name === 'mikro_receipt-proof'));
  const invoke = async (name: string, session?: string) => {
    const before = packets.length;
    const result = toolResultSchema.parse(await client.request('tools/call', { name: 'mikro_receipt-proof', arguments: { prompt: `local ${name} schema fixture`, engine: 'rlm', ...(session ? { session_id: session } : {}) } }, 30000));
    assert.equal(result.content[0].text, result.structuredContent.answer);
    assert.equal(typeof result.structuredContent.session_id, 'string');
    assert.equal(packets.length - before, 1, 'one declared turn, no extra final completion');
    const completeFooter = parseFooter(result.content[0].text);
    assert(completeFooter);
    assert.equal(completeFooter.tokensIn, 11);
    assert.equal(completeFooter.tokensOut, 7);
    outcomes.push({ name, result, completeFooter, packets: packets.length - before });
    return result;
  };
  const invalid = await invoke('output-invalid');
  assert.equal(invalid.isError, true);
  assert(invalid.structuredContent.answer.startsWith('{"wrong":true}'));
  assert.equal(outcomes[0].completeFooter?.validationFailed, true);
  mode = 'valid';
  const corrected = await invoke('valid-resume', invalid.structuredContent.session_id);
  assert.notEqual(corrected.isError, true);
  assert(corrected.structuredContent.answer.startsWith('{"wanted":true}'));
  assert.equal(corrected.structuredContent.session_id, invalid.structuredContent.session_id);
  assert(JSON.stringify(packets[1].request).includes('wrong'), 'failed answer remains in actual resumed history');
  config.output.schema = null;
  await writeFile(configPath, JSON.stringify(config), { mode: 0o600 });
  await writeFile(join(agentDir, 'VALIDATE.md'), `\`\`\`json\n${JSON.stringify(schema)}\n\`\`\`\n`, { mode: 0o600 });
  mode = 'invalid';
  const validateInvalid = await invoke('validate-invalid');
  assert.equal(validateInvalid.isError, true);
  assert(validateInvalid.structuredContent.answer.startsWith('{"wrong":true}'));
  assert.equal(outcomes[2].completeFooter?.validationFailed, true);
} finally {
  client.close();
  await new Promise<void>((resolve, reject) => server.close(error => error ? reject(error) : resolve()));
}
const terminal = terminalProofSchema.parse(JSON.parse(await readFile('/home/genie/.local/share/mikro-engine-split/experiments-g8/g9-terminal-accounting-proof-yMn9hY/proof.json', 'utf8')));
const partialParserResults = terminal.cases.filter(row => row.partialObservation).map(row => ({ name: row.name, parsedCompleteFooter: parseFooter(row.outcome.text), observed: row.partialObservation }));
assert.equal(partialParserResults.length, 2);
for (const result of partialParserResults) assert.equal(result.parsedCompleteFooter, null, 'unchanged Genie parser refuses partial observations as complete bills');
const compiledPaths = ['mikro/dist/src/rlm.js', 'mikro/dist/src/mcp/backends/legacy.js', 'mikro/dist/src/mcp/server.js', 'scripts/mikro/call.ts'];
const compiled = await Promise.all(compiledPaths.map(async path => ({ path, sha256: createHash('sha256').update(await readFile(join(integration, path))).digest('hex') })));
const proof = { schemaVersion: 1, kind: 'actual-compiled-stdio-MCP-and-real-Genie-McpClient-schema-error-resume-parser-smoke', externalModelCalls: 0, realPython: true, localRequests: packets.length, packets, outcomes, partialParserResults, compiled, proofRoot, completeComparisonOrInvoiceClaim: false };
const proofPath = join(proofRoot, 'proof.json');
await writeFile(proofPath, JSON.stringify(proof, null, 2) + '\n', { mode: 0o600, flag: 'wx' });
console.log(JSON.stringify({ proofPath, localRequests: packets.length, outcomes: outcomes.map(({ name, result, completeFooter }) => ({ name, isError: result.isError ?? false, validationFailed: completeFooter?.validationFailed, sessionId: result.structuredContent.session_id })), partialParserResults, externalModelCalls: 0 }));
